import{z as n,x as o,o as e,c as l,q as B,j as r,D as a,d as s,s as t,S as i}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"性能需求的工程化","description":"","frontmatter":{"title":"性能需求的工程化","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pe3-requirements.md","filePath":"cs/pe3-requirements.md","lastUpdated":1791063341000}'),p={name:"cs/pe3-requirements.md"};function d(m,E,D,S,_,C){const A=o("Mermaid");return e(),l("div",null,[E[2]||(E[2]=B('<h1 id="性能需求的工程化" tabindex="-1">性能需求的工程化 <a class="header-anchor" href="#性能需求的工程化" aria-label="Permalink to &quot;性能需求的工程化&quot;">​</a></h1><div class="epigraph"><p>没有数字的性能要求不是需求，是愿望；愿望不占用预算，也不接受验收。</p><footer>—— 据 Beyer 等，Site Reliability Engineering，2016，第 3-4 章的 SLO 口径整理</footer></div><p><a href="/cs/emb-case-map">上一课</a>把嵌入式课程收在三条骨架上：预算按最坏情况记账，信任从独立域出发，承诺都要留下可核查的证据。本课程「性能工程案例」把同一套纪律搬回通用服务，第一课先处理最常被含糊掉的一环：把「系统要快一点」翻译成可以记账、可以核验的工程需求。这是本课程的第一课，后面七课——基准、微基准、回归、容量、长尾、成本、收束——都默认你已经读完本课：没有这里定下的数字与判据，后面的一切测量都没有结论可言。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>「快一点」不可施工。它没有测量对象，没有通过标准，也没有失效时的处置。缺口因此不是优化技术，而是先把承诺变成四个可回答的问题：对<strong>谁</strong>的什么操作快（SLI）；快到<strong>多少</strong>（SLO）；在<strong>什么负载</strong>下（负载模型）；<strong>谁信</strong>（验收协议）。<a href="/cs/obs-slo-engineering">SLO 工程</a>已经给过 SLI 与错误预算的机制，本课不再重讲定义，只解决它们在性能需求里如何落账：性能需求不是一份文档，而是后面每一次测量都要回头对表的判据。不这么做会错在哪：没有判据的团队会把任何一次基准跑赢当成「性能做完了」，等到大促当天才第一次见到真实负载。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>第一步，从用户旅程取 SLI。性能的 SLI 几乎总是成对出现：延迟（一个请求多久返回）与吞吐（一秒能接多少请求），外加资源价格（每请求耗多少毫核、多少字节）。只定 QPS 不定延迟，等于允许用无限延迟换吞吐；只定延迟不定吞吐，等于允许用无限机器换延迟。</p><p>第二步，延迟一律报分位数，不报平均。p99 是一百个请求里最慢的一个；它防的是「平均值漂亮、长尾伤人」的假达标。吞吐与延迟必须<strong>在同一张压测里同时读出</strong>：单独宣称的任何一方都是半张收据。</p><p>第三步，负载模型是需求的一部分。同一服务在均匀小请求下和在突发大请求下是两个系统：请求大小分布、读写比、到达过程（平稳还是突发）、缓存命中率，都得写进需求。换负载模型换结论，这不是测量误差，是换了题目。</p><p><span class="marginnote">「负载模型」翻译成大白话：它是一份「流量画像」——用户通常发多大的请求、读多写少还是写多读少、请求是匀速来还是一阵一阵地挤、缓存平时能挡掉多少。就像健身房测心肺要规定跑步机的速度和坡度，没有画像的压测，测的是谁都不知道的另一种生活。</span></p>',10)),(e(),r(i,null,{default:a(()=>[t(A,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20WISH%5B%22%E6%84%BF%E6%9C%9B%EF%BC%9A%E7%B3%BB%E7%BB%9F%E8%A6%81%E5%BF%AB%E4%B8%80%E7%82%B9%22%5D%20--%3E%20SLI%5B%22SLI%EF%BC%9A%E7%94%A8%E6%88%B7%E6%97%85%E7%A8%8B%E4%B8%8A%E7%9A%84%E6%93%8D%E4%BD%9C%22%5D%0A%20%20SLI%20--%3E%20SLO%5B%22SLO%EF%BC%9A%E5%BB%B6%E8%BF%9F%E5%88%86%E4%BD%8D%E4%B8%8E%E5%90%9E%E5%90%90%E6%88%90%E5%AF%B9%22%5D%0A%20%20SLO%20--%3E%20LOAD%5B%22%E8%B4%9F%E8%BD%BD%E6%A8%A1%E5%9E%8B%EF%BC%9A%E5%A4%A7%E5%B0%8F%E5%88%86%E5%B8%83%E3%80%81%E8%AF%BB%E5%86%99%E6%AF%94%E3%80%81%E5%88%B0%E8%BE%BE%E8%BF%87%E7%A8%8B%22%5D%0A%20%20LOAD%20--%3E%20BUDGET%5B%22%E9%A2%84%E7%AE%97%EF%BC%9A%E8%B5%84%E6%BA%90%E4%BB%B7%E6%A0%BC%E4%B8%8E%E9%94%99%E8%AF%AF%E9%A2%84%E7%AE%97%22%5D%0A%20%20BUDGET%20--%3E%20PROTO%5B%22%E9%AA%8C%E6%94%B6%E5%8D%8F%E8%AE%AE%EF%BC%9A%E7%8E%AF%E5%A2%83%E3%80%81%E6%A0%B7%E6%9C%AC%E9%87%8F%E3%80%81%E5%88%A4%E6%8D%AE%22%5D%0A%20%20PROTO%20--%3E%20EVID%5B%22%E5%8F%AF%E6%A0%B8%E6%9F%A5%E7%9A%84%E8%AF%81%E6%8D%AE%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[s(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>分位数为什么不可替代：请求延迟是重尾分布，平均数可能落在分布里没有任何请求的位置上；p99 却一定对应真实体验的上沿。吞吐与延迟为什么必须成对：压测可以永远把系统压在轻载区刷出好延迟，成对读数才能暴露你所在的工作点。负载模型为什么属于需求：它决定后面的基准设计与容量计算；负载写错，后面每一步都精确地测着一个不存在的系统。</p><p>预算让需求有了花法。<a href="/cs/obs-slo-engineering">SLO 工程</a>的错误预算 \\(1-\\mathrm{SLO}\\) 是可以花的钱：留百分之多少给发布回归、多少给实验、多少给成本优化，本课程后面四类案例——回归、容量、长尾、成本——做的都是花这笔预算的账。<a href="/cs/tail-at-scale">长尾规模</a>则解释了为什么预算要花在分位上：扇出服务里用户等待由最慢分位决定，均值达标换不来体验达标。</p><p><span class="marginnote">p99=200 ms 的直觉账：它是比率不是全员承诺——日请求量 \\(10^8\\) 的服务，p99 之外的慢请求每天仍有 \\(10^6\\) 个。分位数选多严，就是在决定把多大的慢人群算进「达标」。</span></p>',4)),(e(),r(i,null,{default:a(()=>[t(A,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20AVG%5B%22%E5%8F%AA%E6%8A%A5%E5%B9%B3%E5%9D%87%E5%80%BC%EF%BC%9A%E6%AF%94%E5%A6%82%2045%20ms%22%5D%20--%3E%20TAIL%5B%22%E9%87%8D%E5%B0%BE%E5%88%86%E5%B8%83%E4%B8%8B%EF%BC%9A%E5%A4%9A%E6%95%B0%E8%AF%B7%E6%B1%82%2030%20ms%EF%BC%8C%E5%B0%91%E6%95%B0%202%20%E7%A7%92%22%5D%0A%20%20TAIL%20--%3E%20USER%5B%22%E7%94%A8%E6%88%B7%E5%88%B7%E6%96%B0%E5%87%A0%E6%AC%A1%EF%BC%8C%E5%B0%B1%E6%92%9E%E4%B8%8A%E4%B8%80%E6%AC%A1%E6%9E%81%E6%85%A2%22%5D%0A%20%20P99%5B%22%E6%8A%A5%20p99%3D2%20%E7%A7%92%22%5D%20--%3E%20ACT%5B%22%E6%95%B0%E5%AD%97%E6%9A%B4%E9%9C%B2%E4%BA%86%E9%95%BF%E5%B0%BE%EF%BC%8C%E6%89%8D%E8%83%BD%E7%AB%8B%E9%A1%B9%E6%B2%BB%E7%90%86%22%5D%0A%20%20USER%20--%3E%20HIDE%5B%22%E5%9D%87%E5%80%BC%E8%A2%AB%E8%97%8F%E4%BD%8F%EF%BC%8C%E7%9C%8B%E8%B5%B7%E6%9D%A5%E4%B8%80%E5%88%87%E6%AD%A3%E5%B8%B8%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[s(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=B('<p>这张图回答的问题是：为什么平均数会「说谎」？请求延迟是重尾分布——绝大多数请求很快，极少数慢请求把均值轻轻托起，却把个别用户的体验砸穿。平均值 45 ms 可以和「1% 的请求要等 2 秒」并存，而 p99 把这 1% 摆上台面。报哪个数，决定了长尾问题是「不存在」还是「可治理」。</p><p><span class="marginnote">数字实例（错误预算）：SLO 定「p99 ≤ 300 ms 的请求占 99%」，错误预算就是 1%。一个月 3 亿个请求，允许 300 万个超标——这就是可以花掉的钱：发版冒一次烟花 50 万，灰度实验花 100 万，花超了就冻结发布修稳定性，而不是继续叠功能。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>需求只承诺可测的东西。「用 Redis」「上 K8s」是实现，不是需求；把实现写进需求，等于在看见问题之前锁死了解法。SLO 不是 SLA：SLO 是内部目标与预算，SLA 是对外违约条款，后者永远比前者松。数字要可证伪：验收协议必须写明环境、数据、加压方式、样本量与判读规则，否则任何人都能让任何系统「达标」一次。本课程不做的是从第一性原理推导延迟模型——那是主干课排队与体系结构的事，这里只把已知的机制钉进需求格式。</p><p><span class="marginnote">常见误区：以为 SLO 定得越严越好，「全部 100% 达标」显得最有诚意。实际上 100% 意味着零错误预算——一次正常的发版、一次机器重启都在违约，团队从此不敢发布、不敢实验。SLO 的价值恰恰在那可花的 1%：留出犯错的额度，换取可以持续演进的服务。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>性能需求四件套：SLI（谁的操作）、SLO（分位数与吞吐成对）、负载模型、验收协议，缺一不可施工。</li><li>平均数在重尾分布上会落在无人经历的位置；性能承诺报分位，不报均值。</li><li>错误预算让 SLO 从目标变成可花的钱，后续案例都在花这笔预算。</li><li>负载模型属于需求本身：负载写错，等于换了题目再精确作答。</li><li>出处：Beyer 等，<em>Site Reliability Engineering</em>，2016，第 3-4 章；Dean 与 Barroso，<em>The Tail at Scale</em>，CACM 2013；据本课四件套口径整理。</li></ul>',7))])}const h=n(p,[["render",d]]);export{F as __pageData,h as default};
